def solve(s: str) -> str:
    n = len(s)
    if n == 0:
        return ''
    best_start = 0
    best_len = 1
    def expand(l: int, r: int) -> (int, int):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        # now s[l+1:r] is palindrome
        return l + 1, r - (l + 1)
    for i in range(n):
        # odd length
        start, length = expand(i, i)
        if length > best_len:
            best_start, best_len = start, length
        # even length
        start, length = expand(i, i + 1)
        if length > best_len:
            best_start, best_len = start, length
    return s[best_start:best_start+best_len]

