def solve(n):
    """Return the number of prime numbers strictly less than n.
    Handles typical integer inputs and avoids excessive memory for very large n.
    """
    # Convert to int if possible
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # Use sieve for moderate n, else trial division with incremental primes
    THRESH = 2_000_000  # threshold for using sieve (adjustable)
    if n <= THRESH:
        limit = n - 1
        sieve = bytearray(b'\x01') * (limit + 1)
        sieve[0:2] = b'\x00\x00'
        import math
        for p in range(2, int(math.isqrt(limit)) + 1):
            if sieve[p]:
                step = p
                start = p * p
                sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
        return sum(sieve[:n])
    # For large n, count primes using incremental trial division.
    # Keep a list of found primes.
    primes = []
    count = 0
    import math
    for num in range(2, n):
        sqrt_n = int(math.isqrt(num))
        is_prime = True
        for p in primes:
            if p > sqrt_n:
                break
            if num % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
            count += 1
    return count

