def simplify_path(path: str) -> str:
    """Simplify an absolute Unix path.
    Handles '.', '..', multiple slashes, and removes trailing slash (except for root).
    """
    if not path:
        return '/'
    # Ensure path starts with '/'
    # Split by '/', ignore empty components caused by leading/trailing slashes
    parts = path.split('/')
    stack = []
    for part in parts:
