def solve(grid):
    """Count the number of islands in a binary grid.
    An island is a group of adjacent cells with value 1, connected vertically or horizontally.
    The grid may be empty or contain rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    # visited matrix matching each row length
    visited = [ [False]*len(grid[r]) for r in range(rows) ]
    def bfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            i, j = stack.pop()
            for di, dj in ((1,0), (-1,0), (0,1), (0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]) and not visited[ni][nj] and grid[ni][nj] == 1:
