    """Return the length of the longest substring without repeating characters.
    Sliding window with a dictionary mapping characters to their latest index.
    """
    last = {}
    start = 0
    best = 0
    for i,ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        cur = i - start + 1
        if cur > best:
            best = cur
    return best

