def solve(s: str) -> bool:
    """Check if all brackets in the string are balanced and properly nested.
    Considers parentheses (), square brackets [], and curly braces {}.
    Ignores any other characters.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    closing = set(pairs.keys())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in closing:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack
